        "Им оценивают поведение, замечание или поступок: они уместны или неуместны (nicht angebracht, unangebracht). Сочетания: ein angebrachter Ton, eine angebrachte Bemerkung.",
        "В прямом значении angebracht — это также прикреплённый: Das Schild ist an der Tür angebracht (табличка прикреплена к двери). Это та же форма причастия от anbringen (bringt an, brachte an, hat angebracht)."
