        "Формы: er findet sich ab, fand sich ab, hat sich abgefunden. Приставка ab- отделяемая: Ich finde mich damit ab. В Perfekt вспомогательный глагол — haben, а ge вставляется между ab- и основой глагола.",
        "Без возвратного местоимения abfinden означает компенсировать: jemanden mit Geld abfinden (выплатить кому-либо денежную компенсацию)."
