      "translation": "захватывать • захватить • овладевать • овладеть",
      "explanation": [
        "Главное: sich bemächtigen — книжный возвратный глагол, который значит «захватывать в свои руки» — вещь, место или власть, часто силой, а в переносном значении говорится о чувствах, овладевающих человеком.",
        "После sich bemächtigen стоит родительный падеж: sich einer Sache bemächtigen. Формы: bemächtigt sich, bemächtigte sich, hat sich bemächtigt. Приставка be- неотделяемая.",
        "Это слово письменной и литературной речи; в повседневной речи вместо него говорят etwas nehmen или ergreifen."
      ],
      "examples": [
        {
          "de": "Die Rebellen bemächtigten sich der Stadt.",
          "lv": "Мятежники захватили город."
        },
        {
          "de": "Er bemächtigte sich des Autoschlüssels.",
          "lv": "Он завладел ключом от машины."
        },
        {
          "de": "Große Angst bemächtigte sich seiner.",
          "lv": "Им овладел сильный страх."
        },
        {
          "de": "Die Armee hat sich der Macht bemächtigt.",
          "lv": "Армия захватила власть."
        }
      ],
      "comparison": [
        {
          "word": "ergreifen",
          "meaning": "захватывать",
          "example": "Er ergreift die Macht. – Он захватывает власть."
        },
        {
          "word": "sich aneignen",
          "meaning": "присваивать",
          "example": "Er hat sich das Geld angeeignet. – Он присвоил деньги."
        },
        {
          "word": "besetzen",
          "meaning": "оккупировать",
          "example": "Die Soldaten besetzen die Stadt. – Солдаты оккупируют город."
        }
      ],
      "tip": [
        "Запомни родительный падеж: sich des Hauses bemächtigen, sich der Macht bemächtigen.",
        "Ты можешь встретить это слово в исторических текстах, новостях и литературе."
      ],
      "important": [
        "Sich bemächtigen требует родительного падежа, а не винительного.",
        "Не путай с ermächtigen (уполномочивать): это другое слово."
      ],
