      "translation": "своевольный • своенравный • упрямый",
      "explanation": [
        "Главное: eigenwillig — прилагательное, которое описывает человека или вещь со своей волей и стилем: своенравного, упрямого, но часто и своеобразного, оригинального, не следующего за другими.",
        "О человеке слово обычно говорит, что он своенравный, полный собственной воли: ein eigenwilliges Kind. О стиле, интерпретации или вкусе — что они своеобразные: ein eigenwilliger Stil, eine eigenwillige Interpretation.",
        "Слово составлено из eigen (свой) и Wille (воля), поэтому его можно воспринимать как «со своей волей»."
      ],
      "examples": [
        {
          "de": "Sie ist ein eigenwilliges Kind.",
          "lv": "Она — своенравный ребёнок."
        },
        {
          "de": "Er hat eine eigenwillige Art, Probleme zu lösen.",
          "lv": "У него своеобразный способ решать проблемы."
        },
        {
          "de": "Der Künstler ist für seinen eigenwilligen Stil bekannt.",
          "lv": "Художник известен своим своеобразным стилем."
        },
        {
          "de": "Der alte Mann bleibt eigenwillig und lässt sich nichts sagen.",
          "lv": "Старик остаётся упрямым и никого не слушает."
        }
      ],
      "comparison": [
        {
          "word": "eigensinnig",
          "meaning": "своенравный",
          "example": "Das Kind ist eigensinnig. – Ребёнок своенравный."
        },
        {
          "word": "stur",
          "meaning": "упрямый",
          "example": "Er bleibt stur bei seiner Meinung. – Он упрямо стоит на своём мнении."
        },
        {
          "word": "originell",
          "meaning": "оригинальный",
          "example": "Das ist eine originelle Idee. – Это оригинальная идея."
        }
      ],
      "tip": [
        "Значение определяет контекст: ребёнок, пожилой человек — скорее своенравный; стиль, идея — своеобразный.",
        "У слова такие же окончания, как у всех прилагательных: ein eigenwilliger Mensch."
      ],
      "important": [
        "Слово eigenwillig — не willkürlich (случайный, без правил): оно говорит о собственной воле и стиле человека.",
        "Слово может звучать как критически, так и одобрительно; это зависит от предложения."
      ],
