      "translation": "здравица",
      "explanation": [
        "Главное: das Hoch в этом значении — здравица, тост, возглас «да здравствует!», который произносят в честь кого-либо: ein Hoch auf das Brautpaar ausbringen. Это существительное среднего рода, множественное число die Hochs.",
        "То же слово в метеорологии означает антициклон, область высокого давления, которая обычно приносит ясную погоду: ein Hoch über Skandinavien. В переносном значении ein Hoch — это также удачный, полный успехов период.",
        "Прилагательное hoch (высокий) — другое слово, оно пишется со строчной буквы."
      ],
      "examples": [
        {
          "de": "Wir bringen ein Hoch auf das Brautpaar aus.",
          "lv": "Мы поднимаем тост за молодожёнов."
        },
        {
          "de": "Ein dreifaches Hoch auf den Jubilar!",
          "lv": "Трижды да здравствует юбиляр!"
        },
        {
          "de": "Morgen bringt ein Hoch sonniges Wetter.",
          "lv": "Завтра антициклон принесёт солнечную погоду."
        },
        {
          "de": "Nach dem Tief folgt ein Hoch.",
          "lv": "За циклоном следует антициклон."
        }
      ],
      "comparison": [
        {
          "word": "der Toast",
          "meaning": "тост",
          "example": "Er hält einen Toast. – Он произносит тост."
        },
        {
          "word": "das Tief",
          "meaning": "циклон",
          "example": "Das Tief bringt Regen. – Циклон приносит дождь."
        },
        {
          "word": "hoch",
          "meaning": "высокий",
          "example": "Der Berg ist hoch. – Гора высокая."
        }
      ],
      "tip": [
        "Поднимая тост, используй сочетание ein Hoch auf + винительный падеж: auf den Gastgeber.",
        "В прогнозах погоды Hoch — противоположность Tief."
      ],
      "important": [
        "Существительное das Hoch пишется с прописной буквы, прилагательное hoch — со строчной.",
        "Множественное число — die Hochs, а не die Höchen."
      ],
